{"2730111000": {"css": ".card {
  font-family: "Helvetica Neue", "Segoe UI", system-ui, sans-serif;
  font-size: 17px;
  text-align: left;
  color: #e2e8f0;
  background: linear-gradient(135deg, #0f0f1a 0%, #1a1a2e 50%, #16213e 100%);
  padding: 24px;
  line-height: 1.6;
}
.cat {
  display: inline-block; font-size: 12px; color: #8b5cf6; font-weight: 600;
  letter-spacing: 0.5px; text-transform: uppercase;
  padding: 3px 10px; border: 1px solid rgba(139, 92, 246, 0.3);
  border-radius: 10px; margin-bottom: 14px;
}
.front { font-size: 20px; font-weight: 600; color: #f8fafc; }
.back { margin-top: 4px; }
.card b { color: #c4b5fd; }
.card code {
  background: rgba(236, 72, 153, 0.12); padding: 2px 6px; border-radius: 4px;
  color: #f9a8d4; font-family: "SF Mono", Menlo, Consolas, monospace; font-size: 14px;
}
.card pre {
  background: rgba(255, 255, 255, 0.05); padding: 12px 14px; border-radius: 8px;
  border-left: 3px solid #8b5cf6; overflow-x: auto; font-size: 14px;
}
.card pre code { background: none; padding: 0; color: #cbd5e1; }
.card img {
  max-width: 100%; border-radius: 8px; margin: 12px 0;
  border: 1px solid rgba(148, 163, 184, 0.15);
}
.card ul, .card ol { padding-left: 22px; margin: 8px 0; }
.card li { margin: 4px 0; color: #cbd5e1; }
hr { border: none; border-top: 1px solid rgba(148, 163, 184, 0.2); margin: 16px 0; }
